export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity, m = inputs.mass;
  const T = 2 * u / g, apT = u / g, apH = u * u / (2 * g);
  const t = sdk.clamp(time, 0, T);
  const v = u - g * t, y = u * t - g * t * t / 2, F = m * g;
  let st = 'Rising';
  if (t <= 0) st = 'Ready to toss'; else if (Math.abs(t - apT) < 0.005) st = 'At the top'; else if (t >= T - 1e-9) st = 'Back at launch height'; else if (t > apT) st = 'Falling';
  const o = [];
  o.push(...sdk.panel({ id: 'lane.motion', x: 10, y: 36, w: 300, h: 370, title: 'The motion', state: st }));
  o.push(...sdk.panel({ id: 'lane.graph', x: 330, y: 36, w: 300, h: 370, title: 'Velocity over time', state: 'v = u - g t' }));
  o.push(sdk.axis('axis.h', { x: 70, y: 380, length: 300 - 80 + 0, orientation: 'y', min: 0, max: 2.2, ticks: [0, 1, 2], label: 'Height', unit: 'm' }));
  const py = h => 380 - h * (300 / 2.2) * 0.9;
  const by = py(y), bx = 140;
  o.push(sdk.circle('ball.toss', bx, by, 24, {}));
  o.push(...sdk.vector('vec.v', { x: bx, y: by }, { value: v, direction: 'up' }, { scale: 8, label: 'v' }));
  o.push(...sdk.vector('vec.a', { x: bx + 30, y: by }, { value: -g, direction: 'up' }, { scale: 4, label: 'a' }));
  o.push(...sdk.callout(190, 120, ['v = ' + sdk.format(v, 2) + ' m/s', 'a = ' + sdk.format(-g, 1) + ' m/s²', 'Fg = ' + sdk.format(F, 1) + ' N'], { id: 'callout.toss' }));
  const full = sdk.sample(s => [s, u - g * s], 0, T, 20).map(p => ({ x: p[0], y: p[1] }));
  o.push(sdk.plot('plot.vt', { x: 340, y: 60, w: 285, h: 330, axes: { x: { label: 'Time', min: 0, max: 1.8, unit: 's' }, y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' } }, series: [{ label: 'v = u - g t', kind: 'line', points: full }, { label: 'now', kind: 'scatter', points: [{ x: t, y: v }] }] }));
  return { frame: { width: 640, height: 420, objects: o, readouts: [{ id: 'velocity', value: v }, { id: 'acceleration', value: -g }, { id: 'force', value: F }, { id: 'motionState', value: st }] }, quantities: { launchSpeed: u, gravity: g, mass: m, apexTime: apT, apexHeight: apH, height: y, velocity: v, acceleration: -g, force: F } };
}
